<script setup lang="ts">
import {computed,ref} from 'vue';import {supabase} from '@/lib/supabase';import {formatPen,penCents,penDecimal} from '@/lib/financeMoney';import type {Invoice} from '@/types/domain';
export interface OpeningCredit {id:string;available:string;original:string;started_on:string}
export interface OpeningApplication {id:string;created_at:string;motivo:string;reversed:boolean;result:{applied:string}}
const props=defineProps<{credits:OpeningCredit[];applications:OpeningApplication[];invoices:Invoice[];admin:boolean}>();const emit=defineEmits<{changed:[]}>();
const mode=ref(''),source=ref<OpeningCredit|null>(null),application=ref<OpeningApplication|null>(null),selected=ref<string[]>([]),amount=ref(''),reason=ref(''),busy=ref(false),error=ref(''),reviewed=ref(''),request=ref('');
const eligible=computed(()=>props.invoices.filter(i=>i.status==='pending'&&i.finance_reconciled&&penCents(i.amount_due)>0));
const params=()=>mode.value==='apply'?{p_operation_id:request.value,p_source_id:source.value?.id,p_invoice_ids:[...selected.value].sort(),p_amount:penDecimal(penCents(amount.value)),p_reason:reason.value.trim()}:{p_operation_id:request.value,p_application_id:application.value?.id,p_reason:reason.value.trim()};
function begin(c:OpeningCredit){mode.value='apply';source.value=c;application.value=null;selected.value=[];amount.value='';reason.value='';reviewed.value='';error.value='';request.value=crypto.randomUUID();}
function reverse(a:OpeningApplication){mode.value='reverse';application.value=a;source.value=null;selected.value=[];reason.value='';reviewed.value='';error.value='';request.value=crypto.randomUUID();}
function review(){try{if(reason.value.trim().length<5)throw Error('Indica el motivo de la operación.');if(mode.value==='apply'){const n=penCents(amount.value),due=eligible.value.filter(i=>selected.value.includes(i.id)).reduce((n,i)=>n+penCents(i.amount_due),0);if(!selected.value.length||n<=0||n>due||n>penCents(source.value?.available))throw Error('Selecciona mensualidades y un importe dentro del saldo disponible.');}reviewed.value=JSON.stringify(params());error.value='';}catch(e){error.value=String(e);}}
async function confirm(){if(busy.value)return;try{if(!reviewed.value||reviewed.value!==JSON.stringify(params()))throw Error('La revisión cambió. Revisa nuevamente antes de confirmar.');busy.value=true;const {error:e}=await supabase.rpc(mode.value==='apply'?'finance_apply_opening_credit':'finance_reverse_opening_credit',params());if(e)throw Error(e.message);mode.value='';reviewed.value='';emit('changed');}catch(e){error.value=String(e);}finally{busy.value=false;}}
</script>
<template><section v-if="credits.length||applications.length" class="opening-credit"><h3>Saldo inicial a favor conciliado</h3><p class="finance-help">Aplicación manual al contrato seleccionado. No registra dinero nuevo ni genera un recibo de cobro.</p><div v-for="c in credits" :key="c.id" class="finance-history-line">Apertura {{c.started_on}} · Original {{formatPen(c.original)}} · Disponible <b>{{formatPen(c.available)}}</b><button v-if="admin&&penCents(c.available)>0" class="finance-link" @click="begin(c)">Aplicar saldo inicial</button></div><div v-for="a in applications" :key="a.id" class="finance-history-line">{{new Date(a.created_at).toLocaleString('es-PE',{timeZone:'America/Lima'})}} · Aplicado {{formatPen(a.result.applied)}} · {{a.reversed?'Aplicación revertida':'Aplicación vigente'}}<small>{{a.motivo}}</small><button v-if="admin&&!a.reversed" class="finance-link danger" @click="reverse(a)">Revertir aplicación de saldo</button></div>
<form v-if="mode&&admin" class="opening-form" @submit.prevent="review"><h3>{{mode==='apply'?'Aplicar saldo a esta mensualidad':'Revertir aplicación de saldo inicial'}}</h3><template v-if="mode==='apply'"><p class="finance-help">Para otro período, abre su mensualidad en la matriz por PON. El servidor valida nuevamente contrato, deuda y fuente.</p><div class="finance-invoice-options"><label v-for="i in eligible" :key="i.id"><input v-model="selected" type="checkbox" :value="i.id">{{i.period_start}} · {{i.invoice_number}}<b>{{formatPen(i.amount_due)}}</b></label></div><label>Importe PEN<input v-model="amount" aria-label="Importe de saldo inicial" inputmode="decimal" required></label></template><p v-else>Se restituirán {{formatPen(application?.result.applied)}} a la fuente original y se recalcularán las facturas. Se conserva el historial.</p><label>Motivo<input v-model="reason" aria-label="Motivo de saldo inicial" required minlength="5" maxlength="500"></label><p v-if="error" role="alert" class="finance-error">{{error}}</p><p v-if="reviewed" class="finance-rule">{{mode==='apply'?`Saldo inicial después de aplicar: ${formatPen(penDecimal(penCents(source?.available)-penCents(amount)))}`:'Reverso de aplicación revisado.'}} Dinero recibido: S/ 0.00.</p><div class="finance-dialog-actions"><button type="button" class="btn-ghost" :disabled="busy" @click="mode=''">Cancelar</button><button type="submit" class="btn-secondary" :disabled="busy">Revisar aplicación</button><button v-if="reviewed" type="button" class="btn-primary" :disabled="busy" @click="confirm">Confirmar saldo inicial</button></div></form></section></template>
<style scoped>.opening-credit{border-top:1px solid #dce6ed;margin-top:18px;padding-top:10px;font-size:12px}.opening-credit button{margin:8px}.opening-form{background:#f4f8fb;padding:15px;border-radius:6px;margin-top:12px}.opening-form>label{display:flex;flex-direction:column;gap:5px;margin:10px 0}.opening-form input:not([type=checkbox]){border:1px solid #dae4ed;border-radius:5px;padding:8px;max-width:100%;background:white}.opening-form .finance-dialog-actions{flex-wrap:wrap}</style>
